#[derive(serde::Serialize, askama::Template)]
#[template(path = "movie.html")]
struct Movie { title: String, year: u16 }

async fn get_movie(Path(id): Path<u64>, headers: HeaderMap) -> Response {
    let movie = store.find(id).await.unwrap();          // one model
    match pick(&headers) {                              // Accept -> representation
        Media::Json => Json(&movie).into_response(),
        Media::Html => Html(movie.render().unwrap()).into_response(),
    }
}
